using System.Security.Claims;using MachineryManagerEnterprise.Identity.Domain;using MachineryManagerEnterprise.SharedKernel.Abstractions;using Microsoft.AspNetCore.Identity;using Microsoft.Extensions.Options;namespace MachineryManagerEnterprise.Identity.Infrastructure;/// <summary>/// Extends the default principal factory with the user's current/// tenant-scope claims (holding_id / organization_id / project_id),/// sourced through <see cref="IUserAuthorizationScopeResolver"/> —/// Identity consumes the scope but never owns the underlying data/// (ADR-0030). Only IDs are embedded, never display names: names/// change over time, and every claim also flows into the access token./// Applies at every principal creation (password sign-in, authorize,/// token exchange), so claims stay fresh across refresh tokens./// </summary>public sealed class ScopedClaimsPrincipalFactory    : UserClaimsPrincipalFactory<ApplicationUser, ApplicationRole>{    private readonly IUserAuthorizationScopeResolver _scopeResolver;    /// <summary>Initializes a new instance of the <see cref="ScopedClaimsPrincipalFactory"/> class.</summary>    public ScopedClaimsPrincipalFactory(        UserManager<ApplicationUser> userManager,        RoleManager<ApplicationRole> roleManager,        IOptions<IdentityOptions> optionsAccessor,        IUserAuthorizationScopeResolver scopeResolver)        : base(userManager, roleManager, optionsAccessor)    {        _scopeResolver = scopeResolver;    }    /// <inheritdoc />    protected override async Task<ClaimsIdentity> GenerateClaimsAsync(ApplicationUser user)    {        var identity = await base.GenerateClaimsAsync(user);        var scope = await _scopeResolver.ResolveAsync(user.Id);        if (scope is null)        {            return identity;        }        if (scope.OrganizationId is { } organizationId)        {            identity.AddClaim(new Claim("organization_id", organizationId.ToString()));        }        if (scope.HoldingId is { } holdingId)        {            identity.AddClaim(new Claim("holding_id", holdingId.ToString()));        }        if (scope.ProjectId is { } projectId)        {            identity.AddClaim(new Claim("project_id", projectId.ToString()));        }        return identity;    }}